async claim_task(worker_id: string): Promise<Task | null> {
  const pending = await this.queue.listPending();
  if (pending.length === 0) return null;
  const task = pending[0];
  await this.queue.markClaimed(task.id, worker_id);
  await this.workers.recordClaim(worker_id, task.id);
  return task;
}
